package br.com.admeclesial.interfaces.web.sacramento;
import br.com.admeclesial.application.pessoa.PessoaApplicationService; import br.com.admeclesial.application.sacramento.*; import br.com.admeclesial.domain.sacramento.TipoParticipacaoSacramento; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*;
@Controller @RequestMapping("/sacramentos/{sacramentoUuid}/participantes") public class ParticipanteSacramentoWebController {
 private final ParticipanteSacramentoApplicationService service; private final PessoaApplicationService pessoaService;
 public ParticipanteSacramentoWebController(ParticipanteSacramentoApplicationService s,PessoaApplicationService p){service=s;pessoaService=p;}
 @GetMapping public String lista(@PathVariable UUID sacramentoUuid,Model m){m.addAttribute("sacramentoUuid",sacramentoUuid);m.addAttribute("participantes",service.listarPorSacramento(sacramentoUuid));return "participante-sacramento/lista";}
 @GetMapping("/novo") public String novo(@PathVariable UUID sacramentoUuid,Model m){m.addAttribute("sacramentoUuid",sacramentoUuid);m.addAttribute("request",new ParticipanteSacramentoRequest(sacramentoUuid,null,null,null));m.addAttribute("pessoas",pessoaService.listar().stream().filter(x->x.ativo()).toList());m.addAttribute("tipos",TipoParticipacaoSacramento.values());return "participante-sacramento/form";}
 @PostMapping public String criar(@PathVariable UUID sacramentoUuid,@ModelAttribute("request") ParticipanteSacramentoRequest r,Model m){try{service.criar(new ParticipanteSacramentoRequest(sacramentoUuid,r.pessoaUuid(),r.tipoParticipacao(),r.observacao()));return "redirect:/sacramentos/"+sacramentoUuid+"/participantes";}catch(SacramentoBusinessException ex){m.addAttribute("businessError",ex.getMessage());m.addAttribute("sacramentoUuid",sacramentoUuid);m.addAttribute("pessoas",pessoaService.listar().stream().filter(x->x.ativo()).toList());m.addAttribute("tipos",TipoParticipacaoSacramento.values());return "participante-sacramento/form";}}
}
